API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(aws_api_gateway_aws_waf, "AWS API Gateway + AWS WAF", "AWS API Gateway, AWS WAF", "Handles edge routing, TLS 1.3 termination, rate limiting, and DDoS protection.")
    Component(edge_tokenizer_sanitizer, "Edge Tokenizer & Sanitizer", "AWS Lambda", "Performs edge tokenization and PAN data sanitization to enforce PCI-DSS compliance.")
}

Rel(aws_api_gateway_aws_waf, edge_tokenizer_sanitizer, "Invokes synchronous payload validation", "Internal AWS Runtime")

@enduml

Fraud Scoring Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fraud_scoring_engine, "Fraud Scoring Engine") {
    Component(api_handler, "API Handler", "Go", "Routes authorization requests and coordinates the fraud screening workflow.")
    Component(feature_aggregator, "Feature Aggregator", "Go", "Performs parallel feature lookups to construct feature vectors.")
    Component(inference_orchestrator, "Inference Orchestrator", "Go with embedded ONNX Runtime", "Executes in-memory machine learning model inference for fraud scoring.")
    Component(explainability_engine, "Explainability Engine", "Go", "Calculates tree-path contribution scores for decision explainability.")
    Component(buffered_dispatcher, "Buffered Dispatcher", "Go with BadgerDB", "Batches encrypted audit logs and provides ephemeral storage for zero-loss audit queuing.")
}

Rel(api_handler, feature_aggregator, "Requests feature vectors", "In-memory")
Rel(inference_orchestrator, explainability_engine, "Calculates tree-path contribution scores", "In-memory")

@enduml

Amazon ElastiCache for Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Boundary(amazon_elasticache_for_redis, "Amazon ElastiCache for Redis") {
    Component(Redis Feature Store Engine, "Redis Feature Store Engine", "Redis Engine v7.x with Cluster Proxy and AOF Persistence", "Provides sub-millisecond real-time feature lookups using volatile-lru eviction and TTLs.")
}

Rel(Fraud Scoring Engine, Redis Feature Store Engine, "Performs real-time feature lookups", "TCP over TLS")

@enduml

